package org.eclipse.rdf4j.sail.lmdb;

import java.util.concurrent.locks.ReentrantLock;

/**
 * A non-fair {@link ReentrantLock} for gates that every query passes and holds only briefly. A contended acquisition
 * first retries for a bounded number of spins and parks only when the holder is still there afterwards. Parking and
 * waking a thread costs far more than such a gate is held for, so under concurrent queries parking on every collision
 * is what limits throughput. Mutual exclusion, reentrancy, conditions and interruption are those of the superclass.
 */
final class SpinningReentrantLock extends ReentrantLock {

	private static final long serialVersionUID = 1L;

	/**
	 * Attempts made before parking; a few tens of microseconds at most. With a single processor the holder cannot run
	 * while this thread spins, so there it parks at once.
	 */
	private static final int SPINS = Runtime.getRuntime().availableProcessors() > 1 ? 2048 : 0;

	@Override
	public void lock() {
		if (!acquireBySpinning()) {
			super.lock();
		}
	}

	@Override
	public void lockInterruptibly() throws InterruptedException {
		// An interrupt that is already pending is reported by the blocking acquisition.
		if (Thread.currentThread().isInterrupted() || !acquireBySpinning()) {
			super.lockInterruptibly();
		}
	}

	/** Barges exactly as the blocking acquisition of a non-fair lock does, without queueing. */
	private boolean acquireBySpinning() {
		if (super.tryLock()) {
			return true;
		}
		for (int spin = 0; spin < SPINS; spin++) {
			Thread.onSpinWait();
			if (super.tryLock()) {
				return true;
			}
		}
		return false;
	}
}
